// Static HTML/CSS preview of a design system, rendered from its design tokens.
//
// Hosted chat clients cannot run the React showcase, so previews are plain
// HTML styled exclusively with the DS's own CSS custom properties:
//  - ChatGPT renders DS_PREVIEW_WIDGET_HTML inline as an Apps SDK widget
//    (registered as a ui:// resource; data arrives via window.openai.toolOutput).
//  - Claude and other clients get a self-contained document from
//    buildDsPreviewDocument() to render as an HTML artifact.
//
// Fidelity note: real component bodies are Tailwind-built and need a Tailwind
// pass, so the preview shows the system's actual tokens (palette, type, radius,
// shadows) on representative components rather than pixel-perfect React output.

// Minified IIFE bundle of the MCP Apps SDK, inlined into the widget so it runs
// without a runtime CDN import (Claude's sandbox CSP blocks dynamic esm.sh
// imports). Generated by `bun run build:preview-widget`. [BD-92]
import { PREVIEW_WIDGET_SDK_JS } from "./preview-widget-sdk.generated";
import {
  translateClass,
  escapeClassName,
  resolveArbitraryDeclaration,
  TW_DEFAULTS,
} from "./tw-translate";
// Framework-free component-kit CSS (.ds-* classes), styled entirely by the DS
// tokens. Inlined in the widget so the in-widget component showcase renders the
// real component families in the system's own look. [BD-117]
import { DS_KIT_CSS } from "./html-kit";

export interface DsPreviewData {
  /** Display name of the design system or generated project. */
  name: string;
  /** CSS that defines the token custom properties (`:root{--background:...}`). */
  tokensCss: string;
  /** Owner-facing project / DS page on better-design.com (the "Open" link). May require login. */
  viewUrl?: string;
  /** Public, cookieless showcase URL used to generate preview assets. */
  previewUrl?: string;
  /** shadcn install command, when generation has completed. */
  installCommand?: string;
}

/** Rebuild a `:root{}` / `.dark{}` token stylesheet from shadcn registry cssVars. */
export function cssFromRegistryVars(cssVars: {
  light?: Record<string, string>;
  dark?: Record<string, string>;
  theme?: Record<string, string>;
}): string {
  const block = (vars: Record<string, string> | undefined) =>
    Object.entries(vars ?? {})
      .map(([k, v]) => `  --${k.replace(/^--/, "")}: ${v};`)
      .join("\n");
  const root = block({ ...cssVars.theme, ...cssVars.light });
  const dark = block(cssVars.dark);
  return [`:root {\n${root}\n}`, dark ? `.dark {\n${dark}\n}` : ""].filter(Boolean).join("\n");
}

/**
 * Pull the system's typography out of its raw globals.css. The `--font-*`
 * declarations live in the file's `@theme inline` block, which the registry's
 * parsed `cssVars` does NOT carry, and the webfonts themselves are loaded by
 * the Next app (next/font), not by the stylesheet. Without both, previews fall
 * back to system fonts. Returns the font variable declarations plus a Google
 * Fonts `@import` for every named family (the catalog and the generation
 * pipeline both use Google-Fonts-available families); the import must be
 * placed first in the stylesheet. Degrades to the var's own fallback stack if
 * the host blocks external fonts. [BD-84]
 */
export function extractFontCss(rawGlobalsCss: string) {
  // Tailwind's `@theme inline` block aliases each font to itself
  // (`--font-sans: var(--font-sans)`). Copied into :root after the real value,
  // the alias wins, refers to itself and makes the variable invalid, so every
  // preview fell back to the system font. Keep only real values. [BD-1092]
  const decls: string[] = (rawGlobalsCss.match(/--font-(?:sans|serif|mono)\s*:[^;]+;/g) ?? []).filter(
    (decl) => !/^--font-(sans|serif|mono)\s*:\s*var\(\s*--font-\1\s*\)\s*;$/.test(decl),
  );
  // Generated projects declare no --font-* vars; their globals set a plain
  // `font-family:` on body instead. Map the first such stack onto --font-sans
  // so the preview picks up the project's body font. [BD-86]
  if (!decls.length) {
    // Prefer the body rule's stack; only fall back to the first declaration
    // anywhere (which could be a @font-face or component rule) when body
    // declares none.
    const bodyRule = rawGlobalsCss.match(/(?:^|[}\s,])body\s*(?:,[^{]*)?\{[^}]*?font-family\s*:\s*([^;}]+)/);
    const stack = bodyRule?.[1]?.trim() ?? rawGlobalsCss.match(/font-family\s*:\s*([^;}]+)/)?.[1]?.trim();
    if (stack) decls.push(`--font-sans: ${stack};`);
  }
  const families = new Set<string>();
  for (const decl of decls) {
    const value = decl.replace(/^--font-(?:sans|serif|mono)\s*:\s*/, "").replace(/;$/, "");
    for (const m of value.matchAll(/["']([^"']+)["']/g)) addFontFamily(families, m[1]);
    if (!/["']/.test(value)) addFontFamily(families, value.split(",")[0] ?? "");
  }
  const fontImport = families.size
    ? `@import url("https://fonts.googleapis.com/css2?${[...families]
        .map((f) => `family=${encodeURIComponent(f).replace(/%20/g, "+")}:wght@400;500;600;700`)
        .join("&")}&display=swap");`
    : "";
  const fontVars = decls.length ? `:root {\n  ${decls.join("\n  ")}\n}` : "";
  return { fontVars, fontImport };
}

const SYSTEM_FONT_FAMILIES = new Set([
  "arial",
  "georgia",
  "helvetica",
  "menlo",
  "monaco",
  "sans-serif",
  "serif",
  "sfmono-regular",
  "system-ui",
  "times new roman",
  "ui-monospace",
  "ui-sans-serif",
  "ui-serif",
]);

function addFontFamily(families: Set<string>, raw: string): void {
  const family = raw.trim().replace(/^["']|["']$/g, "");
  if (!family || family.startsWith("var(") || SYSTEM_FONT_FAMILIES.has(family.toLowerCase())) return;
  families.add(family);
}

// Tailwind rounded-* utility -> CSS value, honoring the DS's own radius scale
// (catalog systems define --radius-sm/md/lg in @theme per the no-arbitrary-
// values rule; 2xl/3xl fall back to Tailwind defaults).
/** The values `RADIUS_CLASS_TO_CSS` maps its keys onto. */
interface RadiusClassToCssTable {
  [key: string]: string;
}

const RADIUS_CLASS_TO_CSS: RadiusClassToCssTable = {
  "rounded-none": "0",
  "rounded-sm": "var(--radius-sm, calc(var(--radius, 0.5rem) - 4px))",
  "rounded-md": "var(--radius-md, calc(var(--radius, 0.5rem) - 2px))",
  "rounded-lg": "var(--radius-lg, var(--radius, 0.5rem))",
  "rounded-xl": "var(--radius-xl, calc(var(--radius, 0.5rem) + 4px))",
  "rounded-2xl": "var(--radius-2xl, 1rem)",
  "rounded-3xl": "var(--radius-3xl, 1.5rem)",
  rounded: "0.25rem",
  "rounded-full": "9999px",
};

/**
 * Mirror each component's AUTHORED corner radius instead of guessing from the
 * base token: a DS may give its hero button rounded-full while inputs sit at
 * rounded-2xl (editorial-warm does exactly that), so one raw `--radius` on
 * everything reads wrong. Scans the registry/project sources for the button,
 * input, card and badge files and emits override rules for the preview's
 * sample components. Files missing (or no rounded-* class found) keep the
 * base-CSS shadcn-scale fallbacks. [BD-84]
 */
/**
 * Strip JS comments before scanning a component source for Tailwind classes.
 * Prose like "a soft rounded event chip" in a doc comment otherwise matches the
 * bare `rounded` pattern BEFORE the real `rounded-full` class and squares the
 * component (cashmere's Badge shipped 0.25rem instead of a pill). [BD-204]
 */
/** Source with every comment removed, so prose never matches a class pattern. */
export function stripComments(source: string): string {
  return source.replace(/\/\*[\s\S]*?\*\//g, "").replace(/(^|[^:])\/\/[^\n]*/g, "$1");
}

export function componentRadiusCss(files: Array<{ path?: string; content?: string }>): string {
  const radiusFor = (pattern: RegExp): string | null => {
    const file = files.find((f) => f.path && pattern.test(f.path));
    if (!file?.content) return null;
    const m = stripComments(file.content).match(/rounded(?:-(?:none|sm|md|lg|xl|2xl|3xl|full))?(?=[\s"'])/);
    return m ? (RADIUS_CLASS_TO_CSS[m[0]] ?? null) : null;
  };
  const rules: string[] = [];
  // Override both the legacy `.bd-*` primitives and the component-showcase
  // `.ds-*` kit classes, so the showcase honors the DS's authored radii. [BD-117]
  const button = radiusFor(/(^|\/)button\.(tsx|jsx)$/);
  if (button) rules.push(`.bd-btn, .bd-view, .ds-btn { border-radius: ${button}; }`);
  const input = radiusFor(/(^|\/)input\.(tsx|jsx)$/);
  if (input) rules.push(`.bd-input, .ds-input, .ds-textarea, .ds-select { border-radius: ${input}; }`);
  const card = radiusFor(/(^|\/)card\.(tsx|jsx)$/);
  if (card) rules.push(`.bd-card, .ds-card { border-radius: ${card}; }`);
  return rules.join("\n");
}

/**
 * Mirror the DS's primary button MATERIAL, not just its color. The signature
 * fill (custom shadow token, gloss gradient) lives in the button component's
 * `default`/hero cva variant as Tailwind classes (e.g.
 * `shadow-[var(--shadow-pillow-primary)]`, `bg-[linear-gradient(...)]`), which
 * no design token carries. Without this the preview button is a flat
 * `var(--primary)` fill + generic `--shadow-sm`, so every DS reads the same and
 * textured systems look broken. We scope parsing to the `default` variant (the
 * hero treatment per the DS convention) so we never pick up the destructive /
 * secondary shadow, and we only emit overrides when the button actually defines
 * an arbitrary shadow/background — a deliberately FLAT button (plain
 * `bg-primary`, `shadow-none`, or no shadow class) emits nothing and keeps the
 * neutral base, mirroring the DS instead of inventing depth. [BD-116]
 */
// Underscores are spaces in Tailwind arbitrary values (`\_` is a literal
// underscore). Reject anything that could break out of the CSS rule.
function decodeArbitrary(raw: string): string | null {
  const value = raw.replace(/(?<!\\)_/g, " ").replace(/\\_/g, "_").trim();
  return value && !/[<>{};]/.test(value) ? value : null;
}

// Pull a RESTING-state CSS value from a class scope, supporting BOTH Tailwind
// idioms our inputs use, because the AI generation pipeline writes a different
// one than the hand-authored catalog:
//   utility-arbitrary:   shadow-[...]  bg-[...]            (catalog convention)
//   property-arbitrary:  [box-shadow:...]  [background:...] (generator convention)
// State-prefixed variants (hover:/focus:/active:/data-[..]:/group-*:) are skipped
// so we read the resting look, not the hover/checked treatment. [BD-158]
function restingDeclaration(
  scope: string,
  cssProp: string,
  utilPrefixes: string[],
): { property: string; value: string } | null {
  for (const prefix of utilPrefixes) {
    // Not preceded by a word char / `:` (a state modifier like `hover:`) / `.`.
    const m = scope.match(new RegExp(`(?<![\\w:.\\-])${prefix}-\\[([^\\]]+)\\]`));
    if (m) {
      const v = decodeArbitrary(m[1]);
      // `bg-[image:…]` is a background-image, `bg-[oklch(…)]` a background-color:
      // the utility prefix alone does not name the property. [BD-385]
      if (v) return resolveArbitraryDeclaration(prefix, v) ?? { property: cssProp, value: v };
    }
  }
  // `[box-shadow:...]` not preceded by `:` excludes `hover:[box-shadow:...]`.
  const pm = scope.match(new RegExp(`(?<!:)\\[${cssProp}:([^\\]]+)\\]`));
  const decoded = pm ? decodeArbitrary(pm[1]) : null;
  return decoded ? { property: cssProp, value: decoded } : null;
}

function restingValue(scope: string, cssProp: string, utilPrefixes: string[]): string | null {
  const declaration = restingDeclaration(scope, cssProp, utilPrefixes);
  return declaration?.property === cssProp ? declaration.value : null;
}

// Body (class string) of a named cva variant, up to the next variant key. The
// value may be several concatenated quoted strings (`"a " + "b "`). [BD-158]
/** The class string of one named cva variant, or null when the file has none. */
export function variantBody(content: string, name: string): string | null {
  const vi = content.search(/variant\s*:\s*\{/);
  const hay = vi !== -1 ? content.slice(vi) : content;
  const key = name.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const m = hay.match(
    new RegExp(
      `[\\s{,](?:${key}|["']${key}["'])\\s*:\\s*([\\s\\S]*?)(?:\\n\\s*(?:[A-Za-z_][\\w-]*|["'][^"']+["'])\\s*:|\\n\\s*\\},)`,
    ),
  );
  return m ? m[1] : null;
}

/** Does this variant fill itself with the design system's primary token? */
function fillsWithPrimaryToken(body: string): boolean {
  return (
    /(?<![\w-])bg-primary(?![\w-])/.test(body) ||
    /bg-\[[^\]]*--[\w-]*primary/.test(body) ||
    /\[background(?:-image)?:[^\]]*--[\w-]*primary/.test(body)
  );
}

/** The variant React renders when no variant prop is supplied. */
function declaredDefaultVariantBody(content: string): string | null {
  const defaults = content.match(/defaultVariants\s*:\s*\{([\s\S]*?)\}/)?.[1];
  const declaredDefault = defaults?.match(/\bvariant\s*:\s*["']([^"']+)["']/)?.[1];
  return (
    (declaredDefault ? variantBody(content, declaredDefault) : null) ??
    variantBody(content, "default")
  );
}

/**
 * The variant a hero call to action (`.ds-btn-primary`, a storefront's Add to
 * cart) must mirror. Variant NAMES are author-defined and unreliable in both
 * directions: 37 of the 83 catalog systems give `default` a neutral material and
 * keep the accent CTA in a `primary` variant, so binding to the declared default
 * alone rendered the storefront's primary button in the secondary surface with
 * the design system's accent nowhere on the page. Pick by material — the variant
 * that actually fills with the primary token — and fall back to the declared
 * default when no variant does. [BD-385]
 */
export function canonicalButtonVariantBody(content: string): string | null {
  // Copy the material the design system presents as its button, which is the
  // declared default variant. Never derive a fill from --primary.
  //
  // This used to prefer whichever variant filled with the accent token, on the
  // reasoning that a storefront call to action must carry the accent (BD-385).
  // That picks a variant some systems never render. beam-lib's showcase shows a
  // dark pill with a beam rim and keeps its magenta for the rim, links, badges
  // and charts, yet 7 of the 8 buttons on its generated storefront came out
  // magenta. A theme that does not look like the system it was built from is a
  // worse outcome than a call to action in the system's own button colour, and
  // a system whose real button is accent-filled still gets one here, because
  // that is what its default variant says. [BD-456]
  return declaredDefaultVariantBody(content) ?? variantBody(content, "primary");
}

export function componentDepthCss(files: Array<{ path?: string; content?: string }>): string {
  const btn = files.find((f) => f.path && /(^|\/)button\.(tsx|jsx)$/.test(f.path));
  if (!btn?.content) return "";
  const content = btn.content;
  // Hero-CTA scope: mirror the variant React renders when no variant prop is
  // supplied. Variant names are author-defined; `primary` can be an alternate
  // material rather than the component's canonical CTA (Haptic). [BD-385]
  const scope = canonicalButtonVariantBody(content) ?? content;
  const shadow = /(?:^|\s|"|')shadow-none(?=\s|"|'|$)/.test(scope)
    ? "none"
    : restingValue(scope, "box-shadow", ["shadow"]);
  const background =
    restingDeclaration(scope, "background", ["bg"]) ??
    restingDeclaration(scope, "background-image", []);
  // Apply to BOTH the legacy `.bd-*` primitives and the component-showcase
  // `.ds-btn-primary` (the kit class the in-widget showcase renders), so the
  // showcase's hero button carries the DS's real material, not a flat fill. [BD-117]
  const sel = ".bd-btn-primary, .bd-view, .ds-btn-primary";
  const rules: string[] = [];
  if (shadow) rules.push(`${sel} { box-shadow: ${shadow}; }`);
  if (background) rules.push(`${sel} { ${background.property}: ${background.value}; }`);
  return rules.join("\n");
}

// Arbitrary Tailwind value `prefix-[...]`: underscores are spaces; reject
// anything that could break out of the CSS rule. Same contract as componentDepthCss.
function arbitrary(scope: string, re: RegExp): string | null {
  const m = scope.match(re);
  if (!m) return null;
  const value = m[1].replace(/(?<!\\)_/g, " ").replace(/\\_/g, "_").trim();
  return value && !/[<>{};]/.test(value) ? value : null;
}

/**
 * The switch's CHECKED track fill, as the property Tailwind would target. A
 * typed `bg-[image:var(--gradient)]` is a background-image; writing it to the
 * `background` shorthand emits `background: image:var(--gradient)`, which no
 * browser parses, so the DS's filled control silently lost its gradient. [BD-385]
 */
function checkedTrackBackground(
  source: string,
): { property: string; value: string } | null {
  const utility = arbitrary(source, /data-\[state=checked\]:bg-\[([^\]]+)\]/);
  if (utility) {
    return (
      resolveArbitraryDeclaration("bg", utility) ??
      { property: "background", value: utility }
    );
  }
  const image = arbitrary(source, /data-\[state=checked\]:\[background-image:([^\]]+)\]/);
  if (image) return { property: "background-image", value: image };
  const shorthand = arbitrary(source, /data-\[state=checked\]:\[background:([^\]]+)\]/);
  return shorthand ? { property: "background", value: shorthand } : null;
}

// Interactive Radix surfaces have no meaningful resting-state static HTML in the
// kit (their material lives in open/portal state), so the kit can't reproduce
// them. We enumerate the ones a DS actually ships so get-design-system-kit can
// tell the model what's NOT covered and route it to the real components instead
// of silently implying full coverage. [BD-149]
const KIT_INTERACTIVE_EXCLUDED = [
  "dialog", "drawer", "sheet", "dropdown-menu", "context-menu", "menubar",
  "navigation-menu", "command", "combobox", "popover", "hover-card", "tooltip",
  "select", "accordion", "calendar", "carousel", "sonner", "toast", "collapsible",
];

export interface DsComponentKit {
  /** `.ds-*` override rules carrying THIS system's real component material. */
  css: string;
  /** Primitives the kit renders in the system's own look. */
  covered: string[];
  /** Interactive components the kit can't reproduce (use the real React components). */
  excluded: string[];
}

/**
 * Lift each DS's REAL component material onto the framework-free kit classes, so
 * an inline (canvas/artifact) build looks like the system instead of a generic
 * shell. Pure string extraction (no Tailwind compile) so it runs in BOTH the
 * build-time registry generator and the Worker, giving catalog and generated
 * DSes the same fidelity tier. [BD-149]
 *
 * Reuses the proven button radius/depth extraction (componentRadiusCss/
 * componentDepthCss) and extends it to the other static-able primitives: card
 * depth, the switch's CHECKED track material (rule-8 filled control), and badge
 * radius. We read the components' authored Tailwind class strings — including the
 * `data-[state=checked]` / arbitrary `shadow-[...]` material that no design token
 * carries — and only emit when the DS actually defines it (a flat DS emits
 * nothing and keeps the neutral shell). Mirrors the DS, never invents depth.
 */
export function buildDsComponentCss(files: Array<{ path?: string; content?: string }>): DsComponentKit {
  // Comment-stripped: prose in doc comments must never match class patterns
  // (the bare-`rounded` bug that squared cashmere's pill badge). [BD-204]
  const contentOf = (re: RegExp) => stripComments(files.find((f) => f.path && re.test(f.path))?.content ?? "");
  const has = (name: string) => Boolean(contentOf(new RegExp(`(^|/)${name}\\.(tsx|jsx)$`)));
  const rules: string[] = [componentRadiusCss(files), componentDepthCss(files)];
  const covered = new Set<string>();
  for (const name of ["button", "input", "alert", "avatar", "table", "tabs", "progress"]) {
    if (has(name)) covered.add(name);
  }

  // Card: signature depth (soft shadow + edge glow) is an arbitrary shadow on the
  // base class — as a `shadow-[...]` utility OR a `[box-shadow:...]` property. [BD-158]
  const card = contentOf(/(^|\/)card\.(tsx|jsx)$/);
  if (card) {
    covered.add("card");
    const shadow = /shadow-none(?=[\s"'])/.test(card)
      ? "none"
      : restingValue(card, "box-shadow", ["shadow"]);
    if (shadow) rules.push(`.ds-card { box-shadow: ${shadow}; }`);
  }

  // Switch: the CHECKED track is the filled material (rule 8). Mirror the real
  // data-[state=checked] background + shadow onto the kit's `.on` track, reading
  // both the `:shadow-[...]` utility and the `:[box-shadow:...]` property. [BD-158]
  const sw = contentOf(/(^|\/)switch\.(tsx|jsx)$/);
  if (sw) {
    covered.add("switch");
    const bg = checkedTrackBackground(sw);
    const shadow =
      arbitrary(sw, /data-\[state=checked\]:shadow-\[([^\]]+)\]/) ??
      arbitrary(sw, /data-\[state=checked\]:\[box-shadow:([^\]]+)\]/);
    if (bg) rules.push(`.ds-switch-track.on { ${bg.property}: ${bg.value}; }`);
    if (shadow) rules.push(`.ds-switch-track.on { box-shadow: ${shadow}; }`);
  }

  // Badge: authored corner radius (often rounded-full) onto the kit badge.
  const badge = contentOf(/(^|\/)badge\.(tsx|jsx)$/);
  if (badge) {
    covered.add("badge");
    const rm = badge.match(/rounded(?:-(?:none|sm|md|lg|xl|2xl|3xl|full))?(?=[\s"'])/);
    const radius = rm ? RADIUS_CLASS_TO_CSS[rm[0]] : null;
    if (radius) rules.push(`.ds-badge, .ds-badge-primary { border-radius: ${radius}; }`);
  }

  // Input: the field material lives in the shared `formFieldBase` constant
  // (every DS's Input/Textarea imports it per the DS authoring rules), with
  // input.tsx as a fallback for systems that inline it. Lift the authored
  // radius, resting shadow (often an inset highlight) and the SOFT focus ring
  // (`focus-visible:ring-2 ring-ring/NN`) onto the kit fields — without this
  // the kit's generic shell renders a flat field with a harsh focus outline
  // that matches no system. [BD-204]
  const field = contentOf(/(^|\/)_shared\.(ts|tsx)$/) || contentOf(/(^|\/)input\.(tsx|jsx)$/);
  if (field) {
    covered.add("input");
    const fieldSel = ".ds-input, .ds-textarea, .ds-select";
    const rm = field.match(/rounded(?:-(?:none|sm|md|lg|xl|2xl|3xl|full))?(?=[\s"'])/);
    const radius = rm ? RADIUS_CLASS_TO_CSS[rm[0]] : null;
    if (radius) rules.push(`${fieldSel} { border-radius: ${radius}; }`);
    const restShadow = restingValue(field, "box-shadow", ["shadow"]);
    if (restShadow) rules.push(`${fieldSel} { box-shadow: ${restShadow}; }`);
    const ringAlpha = field.match(/focus-visible:ring-2\s+(?:focus-visible:)?ring-ring\/(\d{1,2})/);
    if (ringAlpha) {
      const rest = restShadow ? `${restShadow}, ` : "";
      rules.push(
        `.ds-input:focus, .ds-textarea:focus, .ds-select:focus { outline: none; border-color: var(--ring); box-shadow: ${rest}0 0 0 2px color-mix(in oklab, var(--ring) ${ringAlpha[1]}%, transparent); }`,
      );
    }
  }

  // BD-208: derive each kit component's CSS from the React component's FULL
  // class list (translated wholesale), so the kit matches the DS by
  // construction — padding, typography, radius, colors, shadows, states — not
  // just the single properties the legacy extractors above nibble. Translated
  // rules are appended LAST so they override both the generic shell and the
  // legacy per-property lines; anything the translator cannot express falls
  // through to those earlier rules instead of being invented.
  const translated = translatedKitComponentCss(contentOf, covered);
  if (translated) rules.push(translated);

  const excluded = KIT_INTERACTIVE_EXCLUDED.filter((name) => has(name));
  return { css: rules.filter(Boolean).join("\n"), covered: [...covered].sort(), excluded };
}

/** All string literals inside a source scope, joined into one class string. */
export function quotedStrings(scope: string): string {
  return [...scope.matchAll(/"([^"]*)"|'([^']*)'/g)].map((m) => m[1] ?? m[2]).join(" ");
}

/** The cva() base class string: the first string-literal argument of cva(. */
export function cvaBase(content: string): string | null {
  const i = content.search(/\bcva\s*\(/);
  if (i === -1) return null;
  const tail = content.slice(i, content.search(/variants\s*:/) !== -1 ? content.search(/variants\s*:/) : undefined);
  const s = quotedStrings(tail);
  return s || null;
}

/**
 * Translate a component's class list into ONE kit rule set: base classes merge
 * into `selector { ... }`, state-variant classes (hover:, focus-visible:,
 * disabled:, data-[...]:) bucket into `selector:hover { ... }` etc. Classes the
 * translator does not know (or responsive/file: variants) are skipped — the
 * generic shell keeps covering those properties rather than guessing. [BD-208]
 */
export function kitRuleFromClasses(selector: string, classString: string) {
  const buckets = new Map<string, string[]>();
  let usesTwVars = false;
  for (const cls of new Set(classString.split(/\s+/).filter(Boolean))) {
    const r = translateClass(cls);
    if (!r || r.media || r.body === "") continue;
    const esc = `.${escapeClassName(cls)}`;
    if (!r.selector.startsWith(esc)) continue; // group-/peer- style selectors don't map to one element
    const suffix = r.selector.slice(esc.length);
    if (r.body.includes("--tw-")) usesTwVars = true;
    const bucket = buckets.get(suffix) ?? [];
    bucket.push(r.body.replace(/;\s*$/, ""));
    buckets.set(suffix, bucket);
  }
  const css = [...buckets.entries()]
    .map(([suffix, bodies]) => {
      const sel = selector
        .split(",")
        .map((s) => `${s.trim()}${suffix}`)
        .join(", ");
      return `${sel} { ${bodies.join("; ")} }`;
    })
    .join("\n");
  return { css, usesTwVars };
}

/** Kit selectors derived from each component's own classes. See BD-208. */
function translatedKitComponentCss(
  contentOf: (re: RegExp) => string,
  covered: Set<string>,
): string {
  const out: string[] = [];
  let needsTwDefaults = false;
  const emit = (selector: string, classes: string | null, component?: string) => {
    if (!classes) return;
    const { css, usesTwVars } = kitRuleFromClasses(selector, classes);
    if (css) {
      out.push(css);
      needsTwDefaults ||= usesTwVars;
      if (component) covered.add(component);
    }
  };

  // Badge: cva base + default variant → the kit badge.
  const badge = contentOf(/(^|\/)badge\.(tsx|jsx)$/);
  if (badge) {
    const badgeDefault = variantBody(badge, "default");
    emit(
      ".ds-badge",
      [cvaBase(badge), badgeDefault ? quotedStrings(badgeDefault) : null].filter(Boolean).join(" "),
      "badge",
    );
  }

  // Button: base → .ds-btn; the component's declared default →
  // .ds-btn-primary; named companions map 1:1 when authored.
  const button = contentOf(/(^|\/)button\.(tsx|jsx)$/);
  if (button) {
    emit(".ds-btn", cvaBase(button), "button");
    const canonical = canonicalButtonVariantBody(button);
    // Prefixed with .ds so the copied material outranks the theme's own
    // `.ds a` link colour at (0,1,1). Without it, a link styled as a button
    // takes the link colour and its label can vanish into its own fill. A rule
    // that hardcoded a token here instead was correct only while the button
    // happened to use that token, and broke the moment the material changed.
    // [BD-456]
    emit(".ds .ds-btn-primary", canonical ? quotedStrings(canonical) : null);
    for (const v of ["secondary", "outline", "ghost"]) {
      const body = variantBody(button, v);
      if (body) emit(`.ds .ds-btn-${v}`, quotedStrings(body));
    }
  }

  // Fields: the shared formFieldBase constant (DS authoring rule) or input.tsx.
  const shared = contentOf(/(^|\/)_shared\.(ts|tsx)$/);
  const fieldScope = shared.match(/formFieldBase\s*=([\s\S]*?)(?:\nexport |$)/)?.[1] ?? contentOf(/(^|\/)input\.(tsx|jsx)$/);
  if (fieldScope) {
    emit(".ds-input, .ds-textarea, .ds-select", quotedStrings(fieldScope), "input");
  }

  // Card: the Card root's cn(...) base string.
  const card = contentOf(/(^|\/)card\.(tsx|jsx)$/);
  if (card) {
    const root = card.match(/cn\(\s*([\s\S]*?)(?:,\s*className|\))/)?.[1];
    if (root) emit(".ds-card", quotedStrings(root), "card");
  }

  if (out.length === 0) return "";
  // One preamble for every rule that composes --tw-* variables (ring/transform).
  return (needsTwDefaults ? `${TW_DEFAULTS}\n` : "") + out.join("\n");
}

/** Radius scale declarations from the raw globals.css (@theme block), which parsed cssVars omit. */
export function extractRadiusScaleCss(rawGlobalsCss: string): string {
  const declarations = new Map<string, string>();
  for (const match of rawGlobalsCss.matchAll(/--(radius-[a-z0-9]+)\s*:\s*([^;]+);/gi)) {
    const [, name, value] = match;
    // Tailwind's inline theme bridge can emit `--radius-sm: var(--radius-sm)`
    // after the real :root value. Re-emitting that self-alias overwrites the
    // usable dimension and leaves Figma unable to type the token.
    if (value.trim() === `var(--${name})`) continue;
    declarations.set(name, `--${name}: ${value.trim()};`);
  }
  const decls = [...declarations.values()];
  return decls.length ? `:root {\n  ${decls.join("\n  ")}\n}` : "";
}

/**
 * Shadow scale declarations from the raw globals.css, which parsed cssVars omit
 * just like fonts and the radius scale (BD-84/BD-86). This is what gives a
 * preview its depth and a DS its signature surface: the soft `--shadow-*` ramp
 * plus any inset-highlight "glass" tokens (`--shadow-glass*`). The value match
 * is `[^;]+` so multi-line shadow stacks (inset + outer on separate lines) are
 * captured whole. Without this the preview renders flat. [BD-98]
 */
export function extractShadowScaleCss(rawGlobalsCss: string): string {
  const decls = rawGlobalsCss.match(/--shadow[a-z0-9-]*\s*:[^;]+;/gi) ?? [];
  return decls.length ? `:root {\n  ${decls.join("\n  ")}\n}` : "";
}

